'use strict';
const $=id=>document.getElementById(id);
const HEROES=[{id:'sentinel',name:'อัศวินรอยแยก',role:'ไฟต์เตอร์ · อึดและโจมตีใกล้',icon:'⚔',hp:1400,damage:65,range:90,speed:190,q:'ฟันวงกว้าง',e:'พายุคมดาบ'}, {id:'arcanist',name:'จอมเวทดารา',role:'เมจ · สกิลโจมตีเป็นวงกว้าง',icon:'✦',hp:950,damage:48,range:235,speed:190,q:'ระเบิดดารา',e:'ดาวตก'}, {id:'ranger',name:'นักล่าแสง',role:'แครี่ · ยิงต่อเนื่องจากระยะไกล',icon:'➶',hp:1000,damage:57,range:260,speed:205,q:'ลูกศรกระจาย',e:'พลังนักล่า'}];
const ITEMS=[{id:'blade',name:'ดาบรอยแยก',icon:'⚔',desc:'โจมตี +25',cost:350,damage:25},{id:'boots',name:'รองเท้าลม',icon:'»',desc:'เดินเร็ว +30',cost:250,speed:30},{id:'armor',name:'เกราะพิทักษ์',icon:'⬡',desc:'เลือด +400',cost:400,hp:400},{id:'orb',name:'ผลึกดารา',icon:'✦',desc:'สกิลแรง +30%',cost:450,spell:.3},{id:'fang',name:'เขี้ยวนักล่า',icon:'♢',desc:'ดูดเลือด +12%',cost:400,leech:.12},{id:'haste',name:'นาฬิกากาล',icon:'◷',desc:'คูลดาวน์ลด 15%',cost:350,cdr:.15}];
const canvas=$('arena'),ctx=canvas.getContext('2d');
const WIDTH=1500,HEIGHT=1000;
const BLUE='#60e4db',RED='#ff9168',PURPLE='#c598ff';
const ROUTES=[[[120,840],[150,210],[700,180],[1380,160]],[[120,840],[750,500],[1380,160]],[[120,840],[800,820],[1350,790],[1380,160]]];
let selected=HEROES[0],view={scale:1,x:0,y:0,width:0,height:0};
function chooseHero(id){selected=HEROES.find(h=>h.id===id)||HEROES[0];$('heroName').textContent=selected.name;$('heroRole').textContent=selected.role;$('heroStats').innerHTML=`<div class="stat"><span>พลังชีวิต</span><b>${selected.hp}</b></div><div class="stat"><span>พลังโจมตี</span><b>${selected.damage}</b></div><div class="stat"><span>ระยะโจมตี</span><b>${selected.range}</b></div><div class="stat"><span>ความเร็ว</span><b>${selected.speed}</b></div>`;document.querySelectorAll('.hero-card').forEach(b=>{b.classList.toggle('selected',b.dataset.hero===selected.id);b.setAttribute('aria-pressed',String(b.dataset.hero===selected.id));b.querySelector('.check').textContent=b.dataset.hero===selected.id?'✓':'';});$('qName').textContent=selected.q;$('eName').textContent=selected.e;}
$('heroes').innerHTML=HEROES.map(h=>`<button class="hero-card" data-hero="${h.id}"><span class="check"></span><span class="hero-symbol">${h.icon}</span><b>${h.name}</b><small>${h.role.split(' · ')[0]}</small></button>`).join('');
document.querySelectorAll('[data-hero]').forEach(b=>b.onclick=()=>chooseHero(b.dataset.hero));
$('items').innerHTML=ITEMS.map(i=>`<button class="item" data-item="${i.id}" disabled><span class="item-icon">${i.icon}</span><span class="item-info"><b>${i.name}</b><small>${i.desc}</small></span><em>${i.cost} G</em></button>`).join('');
function resize(){const r=canvas.getBoundingClientRect(),dpr=Math.min(window.devicePixelRatio||1,2);canvas.width=Math.round(r.width*dpr);canvas.height=Math.round(r.height*dpr);view={width:r.width,height:r.height,scale:Math.min(r.width/WIDTH,r.height/HEIGHT),x:0,y:0};view.x=(r.width-WIDTH*view.scale)/2;view.y=(r.height-HEIGHT*view.scale)/2;ctx.setTransform(dpr,0,0,dpr,0,0);draw();}
function ground(){ctx.fillStyle='#0b1923';ctx.fillRect(0,0,WIDTH,HEIGHT);ctx.strokeStyle='#17303b';ctx.lineWidth=1;for(let x=0;x<WIDTH;x+=75){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,HEIGHT);ctx.stroke();}for(let y=0;y<HEIGHT;y+=75){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(WIDTH,y);ctx.stroke();}ctx.beginPath();ctx.moveTo(480,0);ctx.bezierCurveTo(1100,350,400,650,1020,1000);ctx.strokeStyle='#153b4d';ctx.lineWidth=95;ctx.stroke();ctx.strokeStyle='#245267';ctx.lineWidth=2;ctx.stroke();for(const route of ROUTES){ctx.beginPath();route.forEach((p,i)=>i?ctx.lineTo(...p):ctx.moveTo(...p));ctx.strokeStyle='#233c43';ctx.lineWidth=66;ctx.lineJoin='round';ctx.stroke();ctx.strokeStyle='#36535c';ctx.lineWidth=2;ctx.stroke();}ctx.fillStyle='#7892a3';ctx.font='16px "Chakra Petch",sans-serif';ctx.textAlign='center';ctx.fillText('TOP LANE',520,130);ctx.fillText('MID LANE',760,425);ctx.fillText('BOTTOM LANE',1000,890);for(const b of [{x:120,y:840,c:BLUE},{x:1380,y:160,c:RED}]){ctx.strokeStyle=b.c;ctx.lineWidth=2;ctx.beginPath();ctx.arc(b.x,b.y,70,0,Math.PI*2);ctx.stroke();ctx.fillStyle=b.c+'22';ctx.fill();ctx.fillStyle=b.c;ctx.font='48px sans-serif';ctx.fillText('◇',b.x,b.y+16);}}
function draw(){if(game&&view.width<650){view.scale=.72;const p=game.player;view.x=Math.min(0,Math.max(view.width-WIDTH*view.scale,view.width/2-p.x*view.scale));view.y=Math.min(0,Math.max(view.height-HEIGHT*view.scale,view.height*.46-p.y*view.scale));}else {view.scale=Math.min(view.width/WIDTH,view.height/HEIGHT);view.x=(view.width-WIDTH*view.scale)/2;view.y=(view.height-HEIGHT*view.scale)/2;}ctx.save();ctx.clearRect(0,0,view.width,view.height);ctx.translate(view.x,view.y);ctx.scale(view.scale,view.scale);ground();renderBattle();ctx.restore();if(game&&view.width<650)renderMini();}
$('helpBtn').onclick=()=>$('help').showModal();$('closeHelp').onclick=$('understood').onclick=()=>$('help').close();
chooseHero(selected.id);new ResizeObserver(resize).observe(canvas);

let game=null,keys=new Set(),pointer={x:750,y:500},joystick={x:0,y:0},effects=[],lastTime=0,noticeTimer=0,sound=false,audioContext=null,shopPaused=false;
const distance=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y),home=team=>team===0?{x:120,y:840}:{x:1380,y:160};
function routePoint(lane,t){const r=ROUTES[lane],lengths=r.slice(1).map((p,i)=>Math.hypot(p[0]-r[i][0],p[1]-r[i][1])),total=lengths.reduce((a,b)=>a+b,0);let at=t*total;for(let i=0;i<lengths.length;i++){if(at<=lengths[i])return {x:r[i][0]+(r[i+1][0]-r[i][0])*at/lengths[i],y:r[i][1]+(r[i+1][1]-r[i][1])*at/lengths[i]};at-=lengths[i];}return {x:r.at(-1)[0],y:r.at(-1)[1]};}
function notify(msg){$('announcement').textContent=msg;$('announcement').classList.add('show');noticeTimer=3;}
function tone(freq=440,length=.06){if(!sound)return;try{audioContext ||= new (window.AudioContext||window.webkitAudioContext)();const o=audioContext.createOscillator(),g=audioContext.createGain();o.type='sine';o.frequency.value=freq;g.gain.setValueAtTime(.04,audioContext.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioContext.currentTime+length);o.connect(g);g.connect(audioContext.destination);o.start();o.stop(audioContext.currentTime+length);}catch{}}
function entity(type,team,x,y,extra={}){return {id:game.nextId++,type,team,x,y,hp:240,maxHp:240,damage:20,speed:105,range:80,attack:0,radius:12,dead:false,...extra};}
function hero(team,lane,def,player=false){const h=home(team),difficulty=$('difficulty').value,mult=team===1?(difficulty==='easy'?.78:difficulty==='hard'?1.18:1):1;return entity('hero',team,h.x+(team===0?35:-35),h.y+(lane-1)*25,{def,player,lane,hp:def.hp*mult,maxHp:def.hp*mult,damage:def.damage*mult,speed:def.speed,range:def.range,radius:19,level:1,xp:0,gold:500,kills:0,deaths:0,assists:0,inventory:[],cd:{q:0,w:0,e:0},spell:1,leech:0,cdr:0,respawn:0,recall:0,buff:0,rage:0,spin:0,spinTick:0,walkIndex:team===0?1:ROUTES[lane].length-2});}
function startGame(){keys.clear();effects=[];joystick={x:0,y:0};game={time:0,paused:false,finished:false,entities:[],nextId:1,kills:[0,0],wave:3,player:null,towerKills:0};for(let team=0;team<2;team++){const base=home(team);game.entities.push(entity('base',team,base.x,base.y,{hp:2300,maxHp:2300,range:190,damage:100,speed:0,radius:43}));for(let lane=0;lane<3;lane++)for(let n=0;n<2;n++){const p=routePoint(lane,team===0?(n===0?.20:.34):(n===0?.80:.66));game.entities.push(entity('tower',team,p.x,p.y,{hp:1100,maxHp:1100,damage:85,range:205,speed:0,radius:25,lane,inner:n===0}));}for(let i=0;i<5;i++){const def=team===0&&i===0?selected:HEROES[(i+team)%3],h=hero(team,i===0?1:[0,2,1,0][i-1],def,team===0&&i===0);game.entities.push(h);if(h.player)game.player=h;}}
for(const p of [{x:640,y:330},{x:860,y:670}])game.entities.push(entity('monster',2,p.x,p.y,{hp:900,maxHp:900,damage:35,range:130,speed:0,radius:25,respawn:0}));
const p=game.player,rune=$('rune').value;if(rune==='power')p.damage*=1.15;if(rune==='vitality'){p.maxHp*=1.2;p.hp=p.maxHp;}if(rune==='speed')p.speed*=1.15;
$('lobby').hidden=true;$('result').hidden=true;$('pauseOverlay').hidden=true;$('playerHud').hidden=false;$('pauseBtn').hidden=false;$('shopBtn').hidden=false;document.body.classList.add('playing');$('phase').textContent='ดันเลน · ทำลายฐาน';$('modeLabel').textContent='5 ต่อ 5 · '+({easy:'ฝึกหัด',normal:'ปกติ',hard:'ท้าทาย'}[$('difficulty').value]);notify('เริ่มการต่อสู้! เดินตามครีปไปโจมตีป้อม');canvas.focus({preventScroll:true});syncHud();tone(650,.15);}
function lobby(){game=null;effects=[];keys.clear();$('lobby').hidden=false;$('result').hidden=true;$('pauseOverlay').hidden=true;$('playerHud').hidden=true;$('pauseBtn').hidden=true;$('shopBtn').hidden=true;$('shopBtn').textContent='ร้านค้า';document.body.classList.remove('playing','shop-open');shopPaused=false;$('timer').textContent='00:00';$('blueKills').textContent=$('redKills').textContent='0';$('phase').textContent='เตรียมเข้าสู่สนาม';$('gold').textContent='0 G';$('inventory').innerHTML='';delete $('inventory').dataset.items;document.querySelectorAll('[data-item]').forEach(b=>b.disabled=true);}
function pause(value){if(!game||game.finished)return;game.paused=value;$('pauseOverlay').hidden=!value;keys.clear();joystick={x:0,y:0};$('joystick').firstElementChild.style.transform='';}
function move(e,x,y,dt){const dx=x-e.x,dy=y-e.y,d=Math.hypot(dx,dy),step=Math.min(d,e.speed*dt);if(d>1){e.x+=dx/d*step;e.y+=dy/d*step;}e.x=Math.max(45,Math.min(WIDTH-45,e.x));e.y=Math.max(45,Math.min(HEIGHT-45,e.y));}
function enemies(e,range,includeNeutral=false){return game.entities.filter(t=>!t.dead&&t.team!==e.team&&(t.team!==2||includeNeutral)&&distance(e,t)<=range+t.radius);}
function targets(e){return enemies(e,e.range,e.player).filter(t=>t.type!=='base'||baseOpen(t.team));}
function baseOpen(team){return [0,1,2].some(lane=>!game.entities.some(t=>t.type==='tower'&&t.team===team&&t.lane===lane&&!t.dead));}
function heal(e,amount){e.hp=Math.min(e.maxHp,e.hp+amount);}
function gainXp(e,amount){if(e.type!=='hero')return;e.xp+=amount;while(e.xp>=100+e.level*60&&e.level<15){e.xp-=100+e.level*60;e.level++;e.maxHp+=90;e.hp=Math.min(e.maxHp,e.hp+200);e.damage+=6;if(e.player){notify('เลเวล '+e.level+' · พลังชีวิตและพลังโจมตีเพิ่มขึ้น');tone(880,.1);}}}
function damage(target,amount,source){if(target.dead)return;if(target.type==='base'&&!baseOpen(target.team)){if(source.player)notify('ทำลายป้อมทั้งสองในเลนเดียวกัน เพื่อเปิดฐาน');return;}target.hp-=amount;if(target.type==='hero')target.recall=0;if(source.player)target.playerHit=game.time;
effects.push({type:'text',x:target.x,y:target.y-25,text:Math.round(amount),color:source.team===0?BLUE:RED,life:.6,max:.6});if(source.type==='hero'&&source.leech)heal(source,amount*source.leech);
if(target.hp>0)return;target.hp=0;target.dead=true;let reward=0,xp=0;if(target.type==='hero'){target.deaths++;target.respawn=6+target.level*.6;target.destination=null;if(source.team<2)game.kills[source.team]++;reward=200;xp=140;if(source.type==='hero')source.kills++;if(source.team===0&& !source.player&&target.playerHit!==undefined&&game.time-target.playerHit<6)game.player.assists++;if(target.player){notify('คุณถูกสังหาร · เกิดใหม่ใน '+Math.ceil(target.respawn)+' วินาที');tone(180,.25);}else if(source.player){notify('สังหารศัตรู! +200 G');tone(720,.12);}}
else if(target.type==='minion'){reward=40;xp=35;}else if(target.type==='tower'){reward=150;xp=100;if(source.team===0){game.towerKills++;notify('ป้อมศัตรูถูกทำลาย!');}else notify('ป้อมทีมคุณถูกทำลาย');for(const h of game.entities.filter(h=>h.type==='hero'&&h.team===source.team))h.gold+=75;}
else if(target.type==='monster'){reward=130;xp=100;target.respawn=35;if(source.type==='hero'){source.buff=30;heal(source,200);if(source.player)notify('ได้บัฟป่า · โจมตีแรงขึ้น 20% นาน 30 วินาที');}}
else if(target.type==='base'){endGame(source.team===0);return;}
if(source.type==='hero'){source.gold+=reward;gainXp(source,xp);}else if(source.team===0&&distance(source,game.player)<300&&!game.player.dead){game.player.gold+=Math.round(reward*.5);gainXp(game.player,xp*.5);}}
function strike(e,t){if(e.attack>0||!t||t.dead)return;e.attack=e.type==='hero'?(e.def.id==='ranger'?.75:1)*(e.rage>0?.48:1):e.type==='minion'?1.3:1;const dmg=e.damage*(e.buff>0?1.2:1)*(e.rage>0?1.4:1);effects.push({type:'shot',x:e.x,y:e.y,tx:t.x,ty:t.y,color:e.team===0?BLUE:e.team===1?RED:PURPLE,life:.2,max:.2});damage(t,dmg,e);if(e.player)tone(e.range>150?450:260);}
function attackPlayer(){if(!game||game.paused||game.finished||game.player.dead)return;const p=game.player;p.recall=0;const list=targets(p).sort((a,b)=>distance(p,a)-distance(p,b));strike(p,list[0]);if(!list.length)notify('ไม่มีศัตรูในระยะ · เดินเข้าใกล้เป้าหมาย');}
function useSkill(key){if(!game||game.paused||game.finished)return false;const p=game.player;if(p.dead||p.cd[key]>0)return false;p.recall=0;let cooldown=0;if(key==='w'){let dx=pointer.x-p.x,dy=pointer.y-p.y;if(Math.hypot(joystick.x,joystick.y)>.1){dx=joystick.x;dy=joystick.y;}else if(keys.size){dx=(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0);dy=(keys.has('s')||keys.has('arrowdown')?1:0)-(keys.has('w')||keys.has('arrowup')?1:0);}const len=Math.hypot(dx,dy)||1;effects.push({type:'shot',x:p.x,y:p.y,tx:p.x+dx/len*210,ty:p.y+dy/len*210,color:BLUE,life:.35,max:.35});p.x=Math.max(45,Math.min(WIDTH-45,p.x+dx/len*210));p.y=Math.max(45,Math.min(HEIGHT-45,p.y+dy/len*210));p.destination=null;cooldown=8;}
if(key==='q'){const radius=p.def.id==='sentinel'?185:300,amount=(p.def.id==='arcanist'?180:140)+p.level*15;for(const t of enemies(p,radius,true))damage(t,amount*p.spell,p);effects.push({type:'ring',x:p.x,y:p.y,radius,color:p.def.id==='arcanist'?PURPLE:BLUE,life:.5,max:.5});cooldown=6;}
if(key==='e'){cooldown=20;if(p.def.id==='ranger'){p.rage=6;notify('พลังนักล่า · ยิงเร็วและแรงขึ้น 6 วินาที');}else if(p.def.id==='sentinel'){p.spin=3;p.spinTick=0;notify('พายุคมดาบ · โจมตีรอบตัว 3 วินาที');}else{for(const t of enemies(p,350,true))damage(t,(380+p.level*25)*p.spell,p);effects.push({type:'ring',x:p.x,y:p.y,radius:350,color:PURPLE,life:.9,max:.9});}}
p.cd[key]=cooldown*(1-Math.min(.6,p.cdr));tone(key==='e'?140:540,.15);return true;}
function recall(){if(!game||game.paused||game.finished||game.player.dead)return;game.player.recall=4;game.player.destination=null;notify('กำลังกลับฐาน · ยืนนิ่ง 4 วินาที');}
function buy(id){if(!game||game.finished)return {ok:false,reason:'ยังไม่เริ่มแมตช์'};const p=game.player,i=ITEMS.find(i=>i.id===id);if(!i)return {ok:false,reason:'ไม่พบไอเทม'};if(p.inventory.length>=6){notify('ไอเทมเต็ม 6 ช่องแล้ว');return {ok:false,reason:'ช่องไอเทมเต็ม'};}if(p.gold<i.cost){notify('เงินไม่พอซื้อ '+i.name);return {ok:false,reason:'เงินไม่พอ'};}p.gold-=i.cost;p.inventory.push(i);p.damage+=i.damage||0;p.speed+=i.speed||0;if(i.hp){p.maxHp+=i.hp;heal(p,i.hp);}p.spell+=i.spell||0;p.leech+=i.leech||0;p.cdr+=i.cdr||0;notify('ซื้อ '+i.name+' แล้ว');syncHud();tone(820);return {ok:true,gold:Math.floor(p.gold),items:p.inventory.map(i=>i.id)};}
function spawnWave(){for(let team=0;team<2;team++)for(let lane=0;lane<3;lane++)for(let n=0;n<3;n++){const h=home(team);game.entities.push(entity('minion',team,h.x+(team===0?1:-1)*n*20,h.y+n*12,{lane,walkIndex:team===0?1:ROUTES[lane].length-2,damage:20+game.time/40,hp:240+game.time*.3,maxHp:240+game.time*.3}));}}
function followLane(e,dt){const route=ROUTES[e.lane];let p=route[e.walkIndex];if(!p){const b=home(1-e.team);move(e,b.x,b.y,dt);return;}if(distance(e,{x:p[0],y:p[1]})<35)e.walkIndex+=e.team===0?1:-1;move(e,p[0],p[1],dt);}
function updateBot(e,dt){const h=home(e.team);if(e.type==='hero'&&e.hp<e.maxHp*.28){move(e,h.x,h.y,dt);return;}const search=e.type==='hero'?300:e.range+20,candidates=enemies(e,search).filter(t=>t.type!=='base'||baseOpen(t.team));candidates.sort((a,b)=>distance(e,a)-distance(e,b));const t=candidates[0];if(t){if(distance(e,t)<=e.range+t.radius)strike(e,t);else move(e,t.x,t.y,dt);if(e.type==='hero'&&e.cd.q<=0&&distance(e,t)<200){damage(t,(100+e.level*12)*e.spell,e);e.cd.q=7;effects.push({type:'ring',x:e.x,y:e.y,radius:120,color:e.team===0?BLUE:RED,life:.3,max:.3});}}else followLane(e,dt);}
function update(dt){if(!game||game.paused||game.finished)return;game.time+=dt;game.wave-=dt;if(game.wave<=0){spawnWave();game.wave=16;}noticeTimer-=dt;if(noticeTimer<=0)$('announcement').classList.remove('show');const p=game.player;
for(const e of game.entities){if(e.dead){if(e.type==='hero'||e.type==='monster'){e.respawn-=dt;if(e.respawn<=0){e.dead=false;e.hp=e.maxHp;e.attack=0;if(e.type==='hero'){const h=home(e.team);e.x=h.x;e.y=h.y;e.walkIndex=e.team===0?1:ROUTES[e.lane].length-2;e.cd={q:0,w:0,e:0};e.buff=e.rage=e.spin=e.recall=0;if(e.player)notify('เกิดใหม่แล้ว · กลับไปช่วยทีม!');}}}continue;}e.attack=Math.max(0,e.attack-dt);
if(e.type==='hero'){e.gold+=3*dt;for(const k of ['q','w','e'])e.cd[k]=Math.max(0,e.cd[k]-dt);e.buff=Math.max(0,e.buff-dt);e.rage=Math.max(0,e.rage-dt);if(distance(e,home(e.team))<105)heal(e,e.maxHp*.22*dt);if(!e.player&&e.level<Math.min(15,1+Math.floor(game.time/40)))gainXp(e,100+e.level*60);}
if(e.type==='tower'||e.type==='base'){const list=enemies(e,e.range).filter(t=>t.type==='hero'||t.type==='minion').sort((a,b)=>(a.type==='minion'?0:1)-(b.type==='minion'?0:1)||distance(e,a)-distance(e,b));strike(e,list[0]);}
else if(e.type==='monster'){const list=enemies(e,e.range).filter(t=>t.type==='hero');strike(e,list[0]);}
else if(!e.player)updateBot(e,dt);
}
if(!p.dead){let dx=(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0)+joystick.x,dy=(keys.has('s')||keys.has('arrowdown')?1:0)-(keys.has('w')||keys.has('arrowup')?1:0)+joystick.y;const len=Math.hypot(dx,dy);if(len>.1){p.destination=null;p.recall=0;move(p,p.x+dx/len*200,p.y+dy/len*200,dt);}else if(p.destination){p.recall=0;if(distance(p,p.destination)>8)move(p,p.destination.x,p.destination.y,dt);else p.destination=null;}
if(keys.has(' ')){const t=targets(p).sort((a,b)=>distance(p,a)-distance(p,b))[0];p.recall=0;strike(p,t);}if(p.recall>0){p.recall-=dt;if(p.recall<=0){const h=home(0);p.x=h.x;p.y=h.y;notify('กลับฐานแล้ว · ฟื้นฟูพลังชีวิต');}}
if(p.spin>0){p.spin-=dt;p.spinTick-=dt;if(p.spinTick<=0){p.spinTick=.5;for(const t of enemies(p,200,true))damage(t,(75+p.level*8)*p.spell,p);effects.push({type:'ring',x:p.x,y:p.y,radius:200,color:BLUE,life:.45,max:.45});}}}
effects.forEach(f=>f.life-=dt);effects=effects.filter(f=>f.life>0);game.entities=game.entities.filter(e=>!e.dead||e.type!=='minion');syncHud();}
function syncHud(){if(!game)return;const p=game.player;$('gold').textContent=Math.floor(p.gold)+' G';$('timer').textContent=String(Math.floor(game.time/60)).padStart(2,'0')+':'+String(Math.floor(game.time%60)).padStart(2,'0');$('blueKills').textContent=game.kills[0];$('redKills').textContent=game.kills[1];$('playerLevel').textContent='LV '+p.level;$('hpFill').style.width=Math.max(0,p.hp/p.maxHp*100)+'%';$('hpText').textContent=Math.ceil(p.hp)+' / '+Math.round(p.maxHp);$('xpFill').style.width=(p.level===15?100:p.xp/(100+p.level*60)*100)+'%';$('phase').textContent=p.dead?'เกิดใหม่ '+Math.ceil(p.respawn)+' วิ':p.recall>0?'กลับฐาน '+p.recall.toFixed(1)+' วิ':'ดันเลน · ทำลายฐาน';
for(const b of document.querySelectorAll('[data-action]')){const k=b.dataset.action,cd=p.cd[k]||0;b.disabled=p.dead;const i=b.querySelector('i');if(i){b.classList.toggle('cooldown',cd>0);i.textContent=Math.ceil(cd);}}
document.querySelectorAll('[data-item]').forEach(b=>{const i=ITEMS.find(i=>i.id===b.dataset.item);b.disabled=p.gold<i.cost||p.inventory.length>=6||game.finished;});const signature=p.inventory.map(i=>i.id).join(',');if($('inventory').dataset.items!==signature){$('inventory').dataset.items=signature;$('inventory').innerHTML=p.inventory.map(i=>`<span title="${i.name}">${i.icon}</span>`).join('')+Array.from({length:6-p.inventory.length},()=>'<span>·</span>').join('');}}
function endGame(win){if(game.finished)return;game.finished=true;const p=game.player;keys.clear();$('result').hidden=false;$('resultTitle').textContent=win?'ชัยชนะ':'พ่ายแพ้';$('resultTitle').style.color=win?BLUE:RED;$('resultDesc').textContent=win?'ทีมคุณทำลายฐานศัตรูสำเร็จ':'ฐานทีมคุณถูกทำลาย ลองแผนใหม่ในแมตช์ถัดไป';$('resultStats').innerHTML=`<div><b>${p.kills}/${p.deaths}/${p.assists}</b><span>K / D / A</span></div><div><b>${$('timer').textContent}</b><span>เวลาแข่งขัน</span></div><div><b>${game.towerKills}</b><span>ป้อมที่ทีมทำลาย</span></div>`;syncHud();tone(win?740:160,.4);}
function renderBattle(){if(!game)return;const p=game.player;if(!p.dead){ctx.beginPath();ctx.arc(p.x,p.y,p.range,0,Math.PI*2);ctx.strokeStyle=BLUE+'32';ctx.lineWidth=1.5;ctx.stroke();if(p.destination){ctx.strokeStyle=BLUE+'66';ctx.setLineDash([5,8]);ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(p.destination.x,p.destination.y);ctx.stroke();ctx.setLineDash([]);ctx.beginPath();ctx.arc(p.destination.x,p.destination.y,7,0,Math.PI*2);ctx.stroke();}}
for(const e of game.entities){if(e.dead){if(e.player){ctx.fillStyle=BLUE+'77';ctx.font='22px sans-serif';ctx.textAlign='center';ctx.fillText('เกิดใหม่ '+Math.ceil(e.respawn)+'s',e.x,e.y);}continue;}const color=e.team===0?BLUE:e.team===1?RED:PURPLE;ctx.save();ctx.translate(e.x,e.y);if(e.type==='tower'){ctx.fillStyle=color+'0c';ctx.beginPath();ctx.arc(0,0,e.range,0,Math.PI*2);ctx.fill();ctx.strokeStyle=color;ctx.lineWidth=3;ctx.fillStyle='#102331';ctx.beginPath();ctx.rect(-22,-22,44,44);ctx.fill();ctx.stroke();ctx.rotate(Math.PI/4);ctx.fillStyle=color;ctx.fillRect(-9,-9,18,18);ctx.rotate(-Math.PI/4);}else if(e.type==='base'){const open=baseOpen(e.team);ctx.strokeStyle=color;ctx.lineWidth=4;ctx.fillStyle=color+'25';ctx.beginPath();for(let i=0;i<6;i++){const angle=i*Math.PI/3;i?ctx.lineTo(Math.cos(angle)*43,Math.sin(angle)*43):ctx.moveTo(43,0);}ctx.closePath();ctx.fill();ctx.stroke();ctx.fillStyle=color;ctx.font='40px sans-serif';ctx.textAlign='center';ctx.fillText(open?'◇':'⬡',0,13);ctx.font='13px "Noto Sans Thai"';ctx.fillText(open?'ฐานเปิด':'ฐานมีเกราะ',0,75);}else if(e.type==='hero'){if(e.player){ctx.shadowColor=BLUE;ctx.shadowBlur=15;ctx.strokeStyle='#e1fffa';ctx.lineWidth=3;ctx.beginPath();ctx.arc(0,0,25,0,Math.PI*2);ctx.stroke();}ctx.fillStyle=e.player?BLUE:color+'bb';ctx.strokeStyle='#091420';ctx.lineWidth=3;ctx.beginPath();ctx.arc(0,0,19,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.shadowBlur=0;ctx.fillStyle='#081722';ctx.font='bold 22px sans-serif';ctx.textAlign='center';ctx.fillText(e.def.icon,0,8);ctx.fillStyle=e.player?'#fff':color;ctx.font='12px "Noto Sans Thai",sans-serif';ctx.fillText(e.player?'คุณ · '+e.level:(e.team===0?'พันธมิตร':'ศัตรู')+' '+e.level,0,-36);if(e.buff>0||e.rage>0){ctx.strokeStyle=e.rage>0?'#f0cd7c':PURPLE;ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,29,0,Math.PI*2);ctx.stroke();}if(e.recall>0){ctx.strokeStyle=BLUE;ctx.lineWidth=4;ctx.beginPath();ctx.arc(0,0,35,-Math.PI/2,-Math.PI/2+(4-e.recall)/4*Math.PI*2);ctx.stroke();}}
else if(e.type==='monster'){ctx.strokeStyle=PURPLE;ctx.lineWidth=3;ctx.fillStyle='#342749';ctx.beginPath();ctx.moveTo(0,-25);ctx.lineTo(25,0);ctx.lineTo(0,25);ctx.lineTo(-25,0);ctx.closePath();ctx.fill();ctx.stroke();ctx.fillStyle=PURPLE;ctx.font='20px sans-serif';ctx.textAlign='center';ctx.fillText('✦',0,7);}else{ctx.fillStyle=color;ctx.beginPath();ctx.arc(0,0,9,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#132533';ctx.lineWidth=2;ctx.stroke();}
const width=e.type==='minion'?24:e.type==='base'?80:e.type==='tower'?54:45,y=e.type==='base'?-60:e.type==='tower'?-36:e.type==='hero'?-29:-35;ctx.fillStyle='#02080f';ctx.fillRect(-width/2,y,width,5);ctx.fillStyle=color;ctx.fillRect(-width/2,y,width*Math.max(0,e.hp/e.maxHp),5);ctx.restore();}
for(const f of effects){ctx.globalAlpha=Math.max(0,f.life/f.max);if(f.type==='shot'){ctx.strokeStyle=f.color;ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(f.x,f.y);ctx.lineTo(f.tx,f.ty);ctx.stroke();}if(f.type==='ring'){ctx.strokeStyle=f.color;ctx.fillStyle=f.color+'18';ctx.lineWidth=4;ctx.beginPath();ctx.arc(f.x,f.y,f.radius*(1-f.life/f.max*.25),0,Math.PI*2);ctx.fill();ctx.stroke();}if(f.type==='text'){ctx.fillStyle=f.color;ctx.font='bold 17px "Chakra Petch"';ctx.textAlign='center';ctx.fillText(f.text,f.x,f.y-(1-f.life/f.max)*30);}ctx.globalAlpha=1;}}
function frame(now){const dt=Math.min(.05,(now-lastTime)/1000||0);lastTime=now;update(dt);draw();requestAnimationFrame(frame);}
function renderMini(){const w=120,h=80,x=view.width-w-12,y=88,s=w/WIDTH;ctx.fillStyle='#07121eea';ctx.fillRect(x,y,w,h);ctx.strokeStyle='#526779';ctx.lineWidth=1;ctx.strokeRect(x,y,w,h);for(const route of ROUTES){ctx.beginPath();route.forEach((p,i)=>i?ctx.lineTo(x+p[0]*s,y+p[1]*s):ctx.moveTo(x+p[0]*s,y+p[1]*s));ctx.strokeStyle='#3d5361';ctx.stroke();}for(const e of game.entities){if(e.dead||e.type==='minion')continue;ctx.fillStyle=e.player?'#fff':e.team===0?BLUE:e.team===1?RED:PURPLE;ctx.beginPath();ctx.arc(x+e.x*s,y+e.y*s,e.player?3.5:2,0,Math.PI*2);ctx.fill();}ctx.strokeStyle='#fff8';ctx.strokeRect(x+Math.max(0,-view.x/view.scale)*s,y+Math.max(0,-view.y/view.scale)*s,Math.min(WIDTH,view.width/view.scale)*s,Math.min(HEIGHT,view.height/view.scale)*s);}
