window.addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName)||$('help').open)return;const k=e.key.toLowerCase();if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();if(k==='escape'){if(game&&!game.finished)pause(!game.paused);return;}keys.add(k);if(e.repeat)return;if(k==='q'||k==='e')useSkill(k);if(k==='shift')useSkill('w');if(k==='b')recall();});window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>keys.clear());document.addEventListener('visibilitychange',()=>{if(document.hidden)pause(true);});
function canvasPoint(e){const r=canvas.getBoundingClientRect();return {x:(e.clientX-r.left-view.x)/view.scale,y:(e.clientY-r.top-view.y)/view.scale};}canvas.addEventListener('pointermove',e=>pointer=canvasPoint(e));canvas.addEventListener('pointerdown',e=>{if(!game||game.paused||game.finished||game.player.dead||e.button!==0)return;pointer=canvasPoint(e);game.player.destination={x:Math.max(45,Math.min(WIDTH-45,pointer.x)),y:Math.max(45,Math.min(HEIGHT-45,pointer.y))};game.player.recall=0;canvas.focus({preventScroll:true});});canvas.addEventListener('contextmenu',e=>{e.preventDefault();attackPlayer();});
let stickPointer=null;const stick=$('joystick');function updateStick(e){const r=stick.getBoundingClientRect(),dx=e.clientX-r.left-r.width/2,dy=e.clientY-r.top-r.height/2,len=Math.hypot(dx,dy),factor=Math.min(1,35/(len||1));joystick={x:dx*factor/35,y:dy*factor/35};stick.firstElementChild.style.transform=`translate(${dx*factor}px,${dy*factor}px)`;}stick.onpointerdown=e=>{if(stickPointer!==null)return;stickPointer=e.pointerId;stick.setPointerCapture(e.pointerId);updateStick(e);};stick.onpointermove=e=>{if(e.pointerId===stickPointer)updateStick(e);};stick.onpointerup=stick.onpointercancel=e=>{if(e.pointerId!==stickPointer)return;stickPointer=null;joystick={x:0,y:0};stick.firstElementChild.style.transform='';};
